/* shadcn's semantic roles, mapped from Patina's raw tokens so shadcn-shaped code works unchanged. */

:root {
  --background: var(--paper);
  --foreground: var(--ink);
  --card-foreground: var(--ink);
  --popover: var(--card);
  --popover-foreground: var(--ink);
  --primary: var(--ink);
  --primary-foreground: var(--paper);
  --secondary: var(--paper-3);
  --secondary-foreground: var(--ink);
  --muted: var(--paper-2);
  --muted-foreground: var(--ink-2);
  --accent: var(--paper-3);
  --accent-foreground: var(--ink);
  --destructive: var(--ink-red);
  --border: var(--rule);
  --input: var(--line);
  --ring: var(--k-ink);
  /* The first three follow the ink set's drums, so shadcn-style chart configs re-ink with data-inks. */
  --chart-1: var(--print-line);
  --chart-2: var(--print-accent);
  --chart-3: var(--print-detail);
  --chart-4: var(--print-red);
  --chart-5: var(--print-blue);
  --sidebar: var(--paper-2);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--ink);
  --sidebar-primary-foreground: var(--paper);
  --sidebar-accent: var(--paper-3);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: var(--rule);
  --sidebar-ring: var(--k-ink);
  --radius: 4px;
}

/* Paper stocks besides Archive (whose values are the defaults in tokens.css). Each stock sets its paper, reading
   inks, and the text and hand inks derived for it (node tools/check-contrast.mjs --suggest); its grain lives in
   textures.generated.css. The drums themselves stay the same across stocks. */

