/* Patina tokens: the one file that defines raw values (stocks other than Archive live in stocks.css, ink sets in
   inks.css). Type and spacing: Golden Ratio Typography from an 18px body at a 37.5rem measure
   (docs/design-language.md#type-and-spacing). */

:root {
  color-scheme: light;

  /* Paper: Archive stock, day. A warm ivory that has been in a drawer for a while. */
  --paper: #e7dfcc;
  --paper-2: #ddd3be;
  --paper-3: #cfc4ab;
  --card: #f2ebdb;
  --rule: #c4b79d;
  --line: #2f2a22;

  /* Reading inks. Textured paper leaves no room for a faint text grey: --ink-3 still reads at 4.5:1, and the faint
     grey survives as --ink-faint, for disabled text and decorative markers only. */
  --ink: #221d17;
  --ink-2: #4a4237;
  --ink-3: #50493d;
  --ink-faint: #8a7f6c;

  /* Print inks: the drums, named by hue. Patina's own: indigo, plum, rose, verdigris, copper, ochre, oxblood. */
  --print-blue: #304a8c;
  --print-violet: #4a2b5e;
  --print-pink: #d9537c;
  --print-green: #2b8a78;
  --print-orange: #c2602f;
  --print-yellow: #e2a83a;
  --print-red: #9a2f3c;

  /* Text inks: each drum mixed toward --ink until it reads at 4.6:1 on the worst textured surface
     (npm run check:contrast) */
  --ink-blue: #2f4785;
  --ink-violet: #4a2b5e;
  --ink-pink: #753645;
  --ink-green: #265146;
  --ink-orange: #6f3d23;
  --ink-red: #832b35;

  /* Hand inks: handwriting is set large and bold (700, 22.9px), which WCAG counts as large text, so it needs
     3:1 and keeps more of the drum's colour */
  --hand-blue: #304a8c;
  --hand-violet: #4a2b5e;
  --hand-pink: #a4435f;
  --hand-green: #296f60;
  --hand-orange: #9a4f29;
  --hand-red: #9a2f3c;

  /* Context accent: one drum per region (data-ink="…" re-inks a subtree) */
  --k: var(--print-green);
  --k-ink: var(--ink-green);
  --k-hand: var(--hand-green);
  --print-line: var(--print-green);
  --print-accent: var(--print-orange);
  --print-detail: var(--print-violet);

  /* Mark strength */
  --hl-alpha: 48%;
  --wash-alpha: 26%;

  /* Type faces: read, label, annotate */
  --face-read: "Source Serif 4 Variable", "Iowan Old Style", Georgia, serif;
  --face-label:
    "JetBrains Mono Variable", ui-monospace, "SFMono-Regular", Menlo, monospace;
  --face-hand: "Caveat Variable", "Segoe Print", "Bradley Hand", cursive;
  --face-ui: var(--face-read);

  /* Type scale: 18px × φ^(n/2) */
  --type-label: 0.695rem; /* n −2, 11.1px: mono labels */
  --type-small: 0.884rem; /* n −1, 14.2px: compact text, metadata */
  --type-ui: 1rem; /* exception: 16px controls, the size below which iOS zooms inputs */
  --type-button: 0.75rem; /* exception: 12px uppercase mono button labels; at 11px they read too small */
  --type-body: 1.125rem; /* n 0, 18px */
  --type-lead: 1.431rem; /* n 1, 22.9px: h3, lead paragraphs, handwriting */
  --type-h2: 1.82rem; /* n 2, 29.1px */
  --type-h1: 2.315rem; /* n 3, 37.1px */
  --type-title: 2.945rem; /* n 4, 47.1px */
  --type-display: clamp(2.315rem, 1.6rem + 3vw, 3.746rem); /* n 3 → n 5 */

  /* Line heights: tuned for the measure (x-mode linear); headings set tight by design */
  --lh-body: 1.76;
  --lh-lead: 1.6;
  --lh-small: 1.6;
  --lh-ui: 1.4;
  --lh-heading: 1.15;
  --lh-subhead: 1.3; /* headings at lead and body size wrap like prose, so they get more room */
  --lh-display: 1.06;
  --lh-hand: 1.08;
  --measure: 37.5rem; /* about 75 characters of body text */

  /* Spacing: primary line height (31.7px) × φ^n, n = −3…2 */
  --space-hair: 0.469rem; /* 7.5px */
  --space-tight: 0.75rem; /* 12px */
  --space-snug: 1.219rem; /* 19.5px */
  --space-line: 1.969rem; /* 31.5px */
  --space-section: 3.219rem; /* 51.5px */
  --space-page: 5.188rem; /* 83px */

  /* Controls (exception to the scale: touch target and shadcn convention) */
  --control-height: 2.75rem;
  --control-height-compact: 2.25rem;

  /* Surfaces */
  --sheet-radius: 3px 5px 4px 3px;
  --sheet-shadow:
    0 1px 1px rgb(60 40 10 / 0.08), 0 14px 28px -18px rgb(60 40 10 / 0.4);
  --lift-shadow:
    0 1px 1px rgb(60 40 10 / 0.08), 0 22px 36px -20px rgb(60 40 10 / 0.45);
  --duration-lift: 220ms;
}

@media (max-width: 40rem) {
  :root {
    --lh-body: 1.66; /* the narrower phone measure wants less leading */
  }
}

:root[data-theme="night"] {
  color-scheme: dark;

  /* Archive at night: oxidised bronze rather than brown */
  --paper: #191b19;
  --paper-2: #202320;
  --paper-3: #2a2e2a;
  --card: #1f2220;
  --rule: #3c423c;
  --line: #d8d2c2;

  --ink: #ebe5d6;
  --ink-2: #b9b2a2;
  --ink-3: #aaa497;
  --ink-faint: #7d786c;

  --print-blue: #8fa8e8;
  --print-violet: #b9a0d8;
  --print-pink: #f08aaa;
  --print-green: #63c2ae;
  --print-orange: #ee915e;
  --print-yellow: #ecc35e;
  --print-red: #e27a86;

  --ink-blue: var(--print-blue);
  --ink-violet: var(--print-violet);
  --ink-pink: var(--print-pink);
  --ink-green: var(--print-green);
  --ink-orange: var(--print-orange);
  --ink-red: #e48c94;

  --hand-blue: var(--print-blue);
  --hand-violet: var(--print-violet);
  --hand-pink: var(--print-pink);
  --hand-green: var(--print-green);
  --hand-orange: var(--print-orange);
  --hand-red: var(--print-red);

  --hl-alpha: 40%;
  --wash-alpha: 18%;

  --sheet-shadow:
    0 1px 1px rgb(0 0 0 / 0.3), 0 14px 28px -18px rgb(0 0 0 / 0.7);
  --lift-shadow:
    0 1px 1px rgb(0 0 0 / 0.3), 0 22px 36px -20px rgb(0 0 0 / 0.75);
}

/* Variation: lively by default; data-variation="calm" quietens a page or a region, and data-variation="lively"
   brings a region back inside a calm page (a docs demo of a lively mark, say). The nearest marked ancestor wins,
   because each rule sets the values on the marked element itself and its children inherit them. */
:root,
[data-variation="lively"] {
  --misregister: 2.2px;
  --tilt-max: 0.8deg;
  --rough-1: url(#patina-rough-1);
  --rough-2: url(#patina-rough-2);
  --rough-3: url(#patina-rough-3);
  --rough-4: url(#patina-rough-4);
  --rough-5: url(#patina-rough-5);
  --rough-6: url(#patina-rough-6);
}

:root[data-variation="calm"],
[data-variation="calm"] {
  --misregister: 0.6px;
  --tilt-max: 0deg;
  --rough-1: url(#patina-rough-calm-1);
  --rough-2: url(#patina-rough-calm-2);
  --rough-3: url(#patina-rough-calm-3);
  --rough-4: url(#patina-rough-calm-4);
  --rough-5: url(#patina-rough-calm-5);
  --rough-6: url(#patina-rough-calm-6);
}

/* Accent drum: which drum is the document's accent (data-accent on <html>; verdigris when unset). Marks, links,
   focus rings and the spot ink set follow --k; the ink set keeps its own print drums. Ochre has no text ink, so it
   is never the accent. data-ink below still re-inks a region on top. */
:root[data-accent="orange"] {
  --k: var(--print-orange);
  --k-ink: var(--ink-orange);
  --k-hand: var(--hand-orange);
}
:root[data-accent="blue"] {
  --k: var(--print-blue);
  --k-ink: var(--ink-blue);
  --k-hand: var(--hand-blue);
}
:root[data-accent="pink"] {
  --k: var(--print-pink);
  --k-ink: var(--ink-pink);
  --k-hand: var(--hand-pink);
}
:root[data-accent="violet"] {
  --k: var(--print-violet);
  --k-ink: var(--ink-violet);
  --k-hand: var(--hand-violet);
}
:root[data-accent="red"] {
  --k: var(--print-red);
  --k-ink: var(--ink-red);
  --k-hand: var(--hand-red);
}

/* Re-ink a region in one drum. Blue regions print their accent in pink, since their lines are already blue. */
[data-ink="blue"] {
  --k: var(--print-blue);
  --k-ink: var(--ink-blue);
  --k-hand: var(--hand-blue);
  --print-accent: var(--print-pink);
}
[data-ink="pink"] {
  --k: var(--print-pink);
  --k-ink: var(--ink-pink);
  --k-hand: var(--hand-pink);
  --print-accent: var(--print-pink);
}
[data-ink="green"] {
  --k: var(--print-green);
  --k-ink: var(--ink-green);
  --k-hand: var(--hand-green);
  --print-accent: var(--print-green);
}
[data-ink="orange"] {
  --k: var(--print-orange);
  --k-ink: var(--ink-orange);
  --k-hand: var(--hand-orange);
  --print-accent: var(--print-orange);
}
[data-ink="violet"] {
  --k: var(--print-violet);
  --k-ink: var(--ink-violet);
  --k-hand: var(--hand-violet);
  --print-accent: var(--print-violet);
}

/* Compact density, for dense application screens (data-density on <html>). Every spacing unit moves half a step
   down the φ^(n/2) progression the type scale uses (× φ^−½ ≈ 0.786: a 24.9px primary line instead of 31.7px),
   rounded to half pixels, and controls take the compact heights. Type sizes and leading stay; the smallest control
   (30px) stays above the 24px target minimum. */
:root[data-density="compact"] {
  --space-hair: 0.375rem; /* 6px */
  --space-tight: 0.594rem; /* 9.5px */
  --space-snug: 0.969rem; /* 15.5px */
  --space-line: 1.563rem; /* 25px */
  --space-section: 2.531rem; /* 40.5px */
  --space-page: 4.063rem; /* 65px */
  --control-height: 2.25rem; /* 36px */
  --control-height-compact: 1.875rem; /* 30px */
}

/* Interface face (data-face on <html>): Instrument Sans for controls, labels and interface text. Headings, prose,
   and card and dialog titles keep the reading serif through --face-read. */
:root[data-face="sans"] {
  --face-ui:
    "Instrument Sans Variable", "Helvetica Neue", Arial, system-ui, sans-serif;
}

import {
  APPEARANCE,
  defaultAppearance,
  normalize,
  STORAGE_KEY,
  type Appearance,
} from "./appearance"

/**
 * An inline script for <head> that applies the saved appearance before the first paint, so the page never flashes
 * the wrong paper. Pass the same defaults the app uses at runtime. Unknown saved values fall back to the defaults,
 * as normalize() does.
 */
export function appearanceScript(defaults: Appearance = defaultAppearance) {
  const fallback = JSON.stringify(normalize(defaults))
  const options = JSON.stringify(APPEARANCE)
  return `(()=>{const d=${fallback},o=${options};let a={};try{a=JSON.parse(localStorage.getItem(${JSON.stringify(STORAGE_KEY)})||"{}")||{}}catch{}const r=document.documentElement;for(const k in o){if(!o[k].includes(a[k]))a[k]=d[k];if(k!=="theme")r.dataset[k]=a[k]}r.dataset.theme=a.theme==="system"?(matchMedia("(prefers-color-scheme: dark)").matches?"night":"day"):a.theme;r.dataset.themePreference=a.theme})()`
}

// Appearance lives as attributes on <html>, so CSS does the work and every island reads the same state.
// Saved choices persist in localStorage; "system" follows the operating system's light or dark setting.

export const APPEARANCE = {
  theme: ["system", "day", "night"],
  stock: ["archive", "field", "newsprint"],
  /** The print ink sets in styles/inks.css (INK_SETS in ink/inks.ts lists the same five). */
  inks: ["patina", "field", "fluoro", "earth", "spot"],
  /** The drum that is the document's accent, --k. Ochre has no text ink, so it never carries marks. */
  accent: ["green", "orange", "blue", "pink", "violet", "red"],
  variation: ["calm", "lively"],
  patina: ["clean", "handled", "worn"],
  density: ["comfortable", "compact"],
  /** The interface face, --face-ui: the reading serif, or Instrument Sans. Prose keeps the serif. */
  face: ["serif", "sans"],
} as const

export type ThemePreference = (typeof APPEARANCE.theme)[number]
export type Stock = (typeof APPEARANCE.stock)[number]
export type Variation = (typeof APPEARANCE.variation)[number]
export type PatinaLevel = (typeof APPEARANCE.patina)[number]
export type InkSetName = (typeof APPEARANCE.inks)[number]
export type AccentDrum = (typeof APPEARANCE.accent)[number]
export type Density = (typeof APPEARANCE.density)[number]
export type InterfaceFace = (typeof APPEARANCE.face)[number]

export interface Appearance {
  theme: ThemePreference
  stock: Stock
  variation: Variation
  patina: PatinaLevel
  inks: InkSetName
  accent: AccentDrum
  density: Density
  face: InterfaceFace
}

export const defaultAppearance: Appearance = {
  theme: "system",
  stock: "archive",
  variation: "lively",
  patina: "handled",
  inks: "patina",
  accent: "green",
  density: "comfortable",
  face: "serif",
}

export const STORAGE_KEY = "patina-appearance"

const KEYS = Object.keys(APPEARANCE) as (keyof Appearance)[]
/** Settings written to <html> under their own name: data-stock, data-inks, data-accent and so on. */
const ATTRIBUTES = KEYS.filter((key) => key !== "theme")

const pick = <T extends string>(
  options: readonly T[],
  value: unknown,
  fallback: T,
): T => (options.includes(value as T) ? (value as T) : fallback)

/** Keeps only known values, so a stale or hand-edited entry never breaks the page. */
export function normalize(
  value: Partial<Record<keyof Appearance, unknown>>,
  defaults = defaultAppearance,
): Appearance {
  const next: Record<string, string> = {}
  for (const key of KEYS)
    next[key] = pick<string>(APPEARANCE[key], value[key], defaults[key])
  return next as unknown as Appearance
}

export function readSaved(defaults = defaultAppearance): Appearance {
  try {
    return normalize(
      JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}") ?? {},
      defaults,
    )
  } catch {
    return defaults
  }
}

export function save(appearance: Appearance) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appearance))
  } catch {
    // Private windows and blocked storage keep the choice for this page only.
  }
}

export function resolveTheme(theme: ThemePreference): "day" | "night" {
  if (theme !== "system") return theme
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "night"
    : "day"
}

export function apply(
  appearance: Appearance,
  root: HTMLElement = document.documentElement,
) {
  root.dataset.theme = resolveTheme(appearance.theme)
  root.dataset.themePreference = appearance.theme
  for (const key of ATTRIBUTES) root.dataset[key] = appearance[key]
}

/** The appearance currently applied to the document. */
export function current(
  root: HTMLElement = document.documentElement,
): Appearance {
  const value: Partial<Record<keyof Appearance, unknown>> = {
    theme: root.dataset.themePreference,
  }
  for (const key of ATTRIBUTES) value[key] = root.dataset[key]
  return normalize(value)
}

/** The <html> attributes useAppearance watches. */
export const APPEARANCE_ATTRIBUTES = [
  "data-theme-preference",
  ...ATTRIBUTES.map((key) => `data-${key}`),
]

"use client"

import { useCallback, useSyncExternalStore } from "react"
import {
  APPEARANCE_ATTRIBUTES,
  apply,
  current,
  defaultAppearance,
  save,
  type Appearance,
} from "./appearance"

let cache: { key: string; value: Appearance } | undefined

function snapshot(): Appearance {
  const value = current()
  const key = JSON.stringify(value)
  if (cache?.key !== key) cache = { key, value }
  return cache.value
}

function subscribe(onChange: () => void) {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: APPEARANCE_ATTRIBUTES,
  })
  // "system" re-resolves when the operating system switches between light and dark.
  const media = window.matchMedia("(prefers-color-scheme: dark)")
  const follow = () => apply(current())
  media.addEventListener("change", follow)
  return () => {
    observer.disconnect()
    media.removeEventListener("change", follow)
  }
}

/** The document's appearance and a setter that applies and saves a change. Server renders use the defaults. */
export function useAppearance(defaults: Appearance = defaultAppearance) {
  const appearance = useSyncExternalStore(subscribe, snapshot, () => defaults)
  const update = useCallback((change: Partial<Appearance>) => {
    const next = { ...current(), ...change }
    apply(next)
    save(next)
  }, [])
  return [appearance, update] as const
}
